1	import type { TraceLocation, TraceLocationType } from './trace_location';
2	import type { TraceState } from './trace_state';
3	import { TraceMetadataKey } from '../constants';
4	
5	/**
6	 * Interface for token usage information
7	 */
8	export interface TokenUsage {
9	  input_tokens: number;
10	  output_tokens: number;
11	  total_tokens: number;
12	  cache_read_input_tokens?: number;
13	  cache_creation_input_tokens?: number;
14	}
15	
16	/**
17	 * Metadata about a trace, such as its ID, location, timestamp, etc.
18	 */
19	export class TraceInfo {
20	  /**
21	   * The primary identifier for the trace
22	   */
23	  traceId: string;
24	
25	  /**
26	   * The location where the trace is stored
27	   */
28	  traceLocation: TraceLocation;
29	
30	  /**
31	   * Start time of the trace, in milliseconds
32	   */
33	  requestTime: number;
34	
35	  /**
36	   * State of the trace
37	   */
38	  state: TraceState;
39	
40	  /**
41	   * Request to the model/agent (JSON-encoded, may be truncated)
42	   */
43	  requestPreview?: string;
44	
45	  /**
46	   * Response from the model/agent (JSON-encoded, may be truncated)
47	   */
48	  responsePreview?: string;
49	
50	  /**
51	   * Client supplied request ID associated with the trace
52	   */
53	  clientRequestId?: string;
54	
55	  /**
56	   * Duration of the trace, in milliseconds
57	   */
58	  executionDuration?: number;
59	
60	  /**
61	   * Key-value pairs associated with the trace (immutable)
62	   */
63	  traceMetadata: Record<string, string>;
64	
65	  /**
66	   * Tags associated with the trace (mutable)
67	   */
68	  tags: Record<string, string>;
69	
70	  /**
71	   * List of assessments associated with the trace.
72	   * TODO: Assessments are not yet supported in the TypeScript SDK.
73	   */
74	  assessments: any[];
75	
76	  /**
77	   * Create a new TraceInfo instance
78	   * @param params TraceInfo parameters
79	   */
80	  constructor(params: {
81	    traceId: string;
82	    traceLocation: TraceLocation;
83	    requestTime: number;
84	    state: TraceState;
85	    requestPreview?: string;
86	    responsePreview?: string;
87	    clientRequestId?: string;
88	    executionDuration?: number;
89	    traceMetadata?: Record<string, string>;
90	    tags?: Record<string, string>;
91	    assessments?: any[];
92	  }) {
93	    this.traceId = params.traceId;
94	    this.traceLocation = params.traceLocation;
95	    this.requestTime = params.requestTime;
96	    this.state = params.state;
97	    this.requestPreview = params.requestPreview;
98	    this.responsePreview = params.responsePreview;
99	    this.clientRequestId = params.clientRequestId;
100	    this.executionDuration = params.executionDuration;
101	    this.traceMetadata = params.traceMetadata || {};
102	    this.tags = params.tags || {};
103	    // TODO: Assessments are not yet supported in the TypeScript SDK.
104	    this.assessments = [];
105	  }
106	
107	  /**
108	   * Convert this TraceInfo instance to JSON format
109	   * @returns JSON object representation of the TraceInfo
110	   */
111	  toJson(): SerializedTraceInfo {
112	    return {
113	      trace_id: this.traceId,
114	      client_request_id: this.clientRequestId,
115	      trace_location: {
116	        type: this.traceLocation.type,
117	        mlflow_experiment: this.traceLocation.mlflowExperiment
118	          ? {
119	              experiment_id: this.traceLocation.mlflowExperiment.experimentId,
120	            }
121	          : undefined,
122	        inference_table: this.traceLocation.inferenceTable
123	          ? {
124	              full_table_name: this.traceLocation.inferenceTable.fullTableName,
125	            }
126	          : undefined,
127	      },
128	      request_preview: this.requestPreview,
129	      response_preview: this.responsePreview,
130	      request_time: new Date(this.requestTime).toISOString(),
131	      execution_duration:
132	        this.executionDuration != null ? `${this.executionDuration / 1000}s` : undefined,
133	      state: this.state,
134	      trace_metadata: this.traceMetadata,
135	      tags: this.tags,
136	      assessments: this.assessments,
137	    };
138	  }
139	
140	  /**
141	   * Get aggregated token usage information for this trace.
142	   * Returns null if no token usage data is available.
143	   * @returns Token usage object or null
144	   */
145	  get tokenUsage(): TokenUsage | null {
146	    const tokenUsageJson = this.traceMetadata[TraceMetadataKey.TOKEN_USAGE];
147	
148	    if (!tokenUsageJson) {
149	      return null;
150	    }
151	
152	    const usage = JSON.parse(tokenUsageJson) as TokenUsage;
153	    const result: TokenUsage = {
154	      input_tokens: usage.input_tokens,
155	      output_tokens: usage.output_tokens,
156	      total_tokens: usage.total_tokens,
157	    };
158	    if (usage.cache_read_input_tokens != null) {
159	      result.cache_read_input_tokens = usage.cache_read_input_tokens;
160	    }
161	    if (usage.cache_creation_input_tokens != null) {
162	      result.cache_creation_input_tokens = usage.cache_creation_input_tokens;
163	    }
164	    return result;
165	  }
166	
167	  /**
168	   * Create a TraceInfo instance from JSON data
169	   * @param json JSON object containing trace info data
170	   * @returns TraceInfo instance
171	   */
172	  static fromJson(json: SerializedTraceInfo): TraceInfo {
173	    /* eslint-disable @typescript-eslint/no-unsafe-member-access */
174	    return new TraceInfo({
175	      traceId: json.trace_id,
176	      clientRequestId: json.client_request_id,
177	      traceLocation: {
178	        type: json.trace_location?.type as TraceLocationType,
179	        mlflowExperiment: json.trace_location?.mlflow_experiment
180	          ? { experimentId: json.trace_location.mlflow_experiment.experiment_id }
181	          : undefined,
182	        inferenceTable: json.trace_location?.inference_table
183	          ? { fullTableName: json.trace_location.inference_table.full_table_name }
184	          : undefined,
185	      },
186	      requestPreview: json.request_preview,
187	      responsePreview: json.response_preview,
188	      requestTime: json.request_time != null ? new Date(json.request_time).getTime() : Date.now(),
189	      executionDuration:
190	        json.execution_duration != null
191	          ? parseFloat(json.execution_duration.replace('s', '')) * 1000
192	          : undefined,
193	      state: json.state,
194	      traceMetadata: json.trace_metadata || {},
195	      tags: json.tags || {},
196	      assessments: json.assessments || [],
197	    });
198	    /* eslint-enable @typescript-eslint/no-unsafe-member-access */
199	  }
200	}
201	
202	export interface SerializedTraceInfo {
203	  trace_id: string;
204	  client_request_id?: string;
205	  trace_location: {
206	    type: TraceLocationType;
207	    mlflow_experiment?: {
208	      experiment_id: string;
209	    };
210	    inference_table?: {
211	      full_table_name: string;
212	    };
213	  };
214	  request_preview?: string;
215	  response_preview?: string;
216	  // "request_time": "2025-06-15T14:07:41.282Z"
217	  request_time: string;
218	  execution_duration?: string;
219	  state: TraceState;
220	  trace_metadata: Record<string, string>;
221	  tags: Record<string, string>;
222	  // TODO: Define proper type for assessments once supported
223	  assessments: any[];
224	}
