1	import { trace, Tracer } from '@opentelemetry/api';
2	import { MlflowSpanExporter, MlflowSpanProcessor } from '../exporters/mlflow';
3	import { NodeSDK } from '@opentelemetry/sdk-node';
4	import { getConfig, getAuthProvider } from './config';
5	import { MlflowClient } from '../clients';
6	
7	let sdk: NodeSDK | null = null;
8	// Keep a reference to the span processor for flushing
9	let processor: MlflowSpanProcessor | null = null;
10	
11	export function initializeSDK(): void {
12	  if (sdk) {
13	    sdk.shutdown().catch((error) => {
14	      console.error('Error shutting down existing SDK:', error);
15	    });
16	  }
17	
18	  try {
19	    const config = getConfig();
20	    const authProvider = getAuthProvider();
21	
22	    const client = new MlflowClient({
23	      trackingUri: config.trackingUri,
24	      authProvider,
25	    });
26	    const exporter = new MlflowSpanExporter(client);
27	    processor = new MlflowSpanProcessor(exporter);
28	
29	    sdk = new NodeSDK({ spanProcessors: [processor] });
30	    sdk.start();
31	  } catch (error) {
32	    console.error('Failed to initialize MLflow tracing:', error);
33	  }
34	}
35	
36	export function getTracer(module_name: string): Tracer {
37	  return trace.getTracer(module_name);
38	}
39	
40	/**
41	 * Force flush all pending trace exports.
42	 */
43	export async function flushTraces(): Promise<void> {
44	  await processor?.forceFlush();
45	}
