1	import { Trace } from '../core/entities/trace';
2	import { ExportResult } from '@opentelemetry/core';
3	import {
4	  Span as OTelSpan,
5	  SpanProcessor,
6	  ReadableSpan as OTelReadableSpan,
7	  SpanExporter,
8	} from '@opentelemetry/sdk-trace-base';
9	import { Context } from '@opentelemetry/api';
10	import { createAndRegisterMlflowSpan } from '../core/api';
11	import { getConfiguredTraceMetadata, getConfiguredTraceTags } from '../core/context';
12	import { InMemoryTraceManager } from '../core/trace_manager';
13	import { TraceInfo } from '../core/entities/trace_info';
14	import { createTraceLocationFromExperimentId } from '../core/entities/trace_location';
15	import { fromOtelStatus, TraceState } from '../core/entities/trace_state';
16	import {
17	  SpanAttributeKey,
18	  TRACE_ID_PREFIX,
19	  TRACE_SCHEMA_VERSION,
20	  TraceMetadataKey,
21	} from '../core/constants';
22	import { convertHrTimeToMs, aggregateUsageFromSpans } from '../core/utils';
23	import { getConfig } from '../core/config';
24	import { MlflowClient } from '../clients';
25	import { executeOnSpanEndHooks, executeOnSpanStartHooks } from './span_processor_hooks';
26	
27	/**
28	 * Generate a MLflow-compatible trace ID for the given span.
29	 * @param span The span to generate the trace ID for
30	 */
31	function generateTraceId(span: OTelSpan): string {
32	  // NB: trace Id is already hex string in Typescript OpenTelemetry SDK
33	  return TRACE_ID_PREFIX + span.spanContext().traceId;
34	}
35	
36	export class MlflowSpanProcessor implements SpanProcessor {
37	  private _exporter: SpanExporter;
38	
39	  constructor(exporter: SpanExporter) {
40	    this._exporter = exporter;
41	  }
42	
43	  /**
44	   * Called when a {@link Span} is started, if the `span.isRecording()`
45	   * returns true.
46	   * @param span the Span that just started.
47	   */
48	  onStart(span: OTelSpan, _parentContext: Context): void {
49	    const otelTraceId = span.spanContext().traceId;
50	
51	    let traceId: string;
52	    const experimentId = getConfig().experimentId;
53	
54	    if (!span.parentSpanContext?.spanId) {
55	      // This is a root span
56	      traceId = generateTraceId(span);
57	
58	      // Build trace metadata, merging context-injected values
59	      const traceMetadata: Record<string, string> = {
60	        [TraceMetadataKey.SCHEMA_VERSION]: TRACE_SCHEMA_VERSION,
61	      };
62	      const ctxMetadata = getConfiguredTraceMetadata();
63	      if (ctxMetadata) {
64	        Object.assign(traceMetadata, ctxMetadata);
65	      }
66	
67	      // Build trace tags, merging context-injected values
68	      const tags: Record<string, string> = {};
69	      const ctxTags = getConfiguredTraceTags();
70	      if (ctxTags) {
71	        Object.assign(tags, ctxTags);
72	      }
73	
74	      const trace_info = new TraceInfo({
75	        traceId: traceId,
76	        traceLocation: createTraceLocationFromExperimentId(experimentId),
77	        requestTime: convertHrTimeToMs(span.startTime),
78	        executionDuration: 0,
79	        state: TraceState.IN_PROGRESS,
80	        traceMetadata,
81	        tags,
82	        assessments: [],
83	      });
84	      InMemoryTraceManager.getInstance().registerTrace(otelTraceId, trace_info);
85	    } else {
86	      traceId = InMemoryTraceManager.getInstance().getMlflowTraceIdFromOtelId(otelTraceId) || '';
87	
88	      if (!traceId) {
89	        console.warn(`No trace ID found for span ${span.name}. Skipping.`);
90	        return;
91	      }
92	    }
93	
94	    // Set trace ID to the span
95	    span.setAttribute(SpanAttributeKey.TRACE_ID, JSON.stringify(traceId));
96	
97	    createAndRegisterMlflowSpan(span);
98	    executeOnSpanStartHooks(span);
99	  }
100	
101	  /**
102	   * Called when a {@link ReadableSpan} is ended, if the `span.isRecording()`
103	   * returns true.
104	   * @param span the Span that just ended.
105	   */
106	  onEnd(span: OTelReadableSpan): void {
107	    const traceManager = InMemoryTraceManager.getInstance();
108	
109	    executeOnSpanEndHooks(span);
110	
111	    // Only trigger trace export for root span completion
112	    if (span.parentSpanContext?.spanId) {
113	      return;
114	    }
115	
116	    // Update trace info
117	    const traceId = traceManager.getMlflowTraceIdFromOtelId(span.spanContext().traceId);
118	    if (!traceId) {
119	      console.warn(`No trace ID found for span ${span.name}. Skipping.`);
120	      return;
121	    }
122	
123	    const trace = InMemoryTraceManager.getInstance().getTrace(traceId);
124	    if (!trace) {
125	      console.warn(`No trace found for span ${span.name}. Skipping.`);
126	      return;
127	    }
128	
129	    this.updateTraceInfo(trace.info, span);
130	    // Aggregate token usage from all spans and add to trace metadata
131	    const allSpans = Array.from(trace.spanDict.values());
132	    const aggregatedUsage = aggregateUsageFromSpans(allSpans);
133	    if (aggregatedUsage) {
