94	function tryExtractMessages(obj: Record<string, unknown>): Record<string, unknown>[] | null {
95	  // OpenAI ChatCompletion request format: { messages: [...] }
96	  if (Array.isArray(obj.messages)) {
97	    return obj.messages.filter(isMessage);
98	  }
99	
100	  // OpenAI ChatCompletion response format: { choices: [{ message: {...} }] }
101	  if (
102	    Array.isArray(obj.choices) &&
103	    obj.choices.length > 0 &&
104	    typeof obj.choices[0] === 'object' &&
105	    obj.choices[0] != null
106	  ) {
107	    const msg = (obj.choices[0] as Record<string, unknown>).message;
108	    if (isMessage(msg)) {
109	      return [msg];
110	    }
111	  }
112	
113	  // OpenAI Responses API request format: { input: [...] }
114	  if (Array.isArray(obj.input)) {
115	    return obj.input.filter(isMessage);
116	  }
117	
118	  // OpenAI Responses API response format: { output: [...] }
119	  if (Array.isArray(obj.output)) {
120	    return obj.output.filter(isMessage);
121	  }
122	
123	  // ResponsesAgent input: { request: { ... } }
124	  if (obj.request && typeof obj.request === 'object') {
125	    return tryExtractMessages(obj.request as Record<string, unknown>);
