6	/**
7	 * Error thrown when an HTTP request to the MLflow backend returns a non-2xx response.
8	 * Carries the parsed status code and (when present) the `error_code` field from the
9	 * response body so callers can branch on status without matching error messages.
10	 */
11	export class MlflowHttpError extends Error {
12	  readonly status: number;
13	  readonly statusText: string;
14	  readonly body: string;
15	  readonly errorCode?: string;
16	
17	  constructor(status: number, statusText: string, body: string) {
18	    super(MlflowHttpError.formatMessage(status, statusText, body));
19	    this.name = 'MlflowHttpError';
20	    this.status = status;
21	    this.statusText = statusText;
22	    this.body = body;
23	    this.errorCode = MlflowHttpError.extractErrorCode(body);
24	  }
25	
26	  private static formatMessage(status: number, statusText: string, body: string): string {
27	    let message = `HTTP ${status}: ${statusText}`;
28	    if (body) {
29	      message +=
30	        body.length > MAX_ERROR_BODY_LENGTH
31	          ? ` - ${body.substring(0, MAX_ERROR_BODY_LENGTH)}... (truncated)`
32	          : ` - ${body}`;
33	    }
34	    return message;
35	  }
36	
37	  private static extractErrorCode(body: string): string | undefined {
38	    if (!body) {
39	      return undefined;
40	    }
41	    try {
42	      const parsed: unknown = JSON.parse(body);
43	      if (
44	        parsed &&
45	        typeof parsed === 'object' &&
46	        'error_code' in parsed &&
47	        typeof (parsed as { error_code: unknown }).error_code === 'string'
48	      ) {
49	        return (parsed as { error_code: string }).error_code;
50	      }
51	    } catch {
52	      // body is not JSON
53	    }
54	    return undefined;
55	  }
56	}
