58	/**
59	 * Make a request to the given URL with the given method, headers, body, and timeout.
60	 *
61	 * TODO: add retry logic for transient errors
62	 */
63	export async function makeRequest<T>(
64	  method: string,
65	  url: string,
66	  headerProvider: HeadersProvider,
67	  body?: any,
68	  timeout?: number,
69	): Promise<T> {
70	  const controller = new AbortController();
71	  const timeoutId = setTimeout(() => controller.abort(), timeout ?? getDefaultTimeout());
72	  const headers = await headerProvider();
73	
74	  try {
75	    const response = await fetch(url, {
76	      method,
77	      headers: headers,
78	      body: body ? JSONBig.stringify(body) : undefined,
79	      signal: controller.signal,
80	    });
81	
82	    clearTimeout(timeoutId);
83	
84	    if (!response.ok) {
85	      let responseBody = '';
86	      try {
87	        responseBody = await response.text();
88	      } catch {
89	        // If we can't read the body, leave it empty
90	      }
91	      throw new MlflowHttpError(response.status, response.statusText, responseBody);
92	    }
93	
94	    // Handle empty responses (like DELETE operations)
95	    if (response.status === 204 || response.headers.get('content-length') === '0') {
96	      return {} as T;
97	    }
98	
99	    const responseText = await response.text();
100	    return JSONBig.parse(responseText) as T;
101	  } catch (error) {
102	    clearTimeout(timeoutId);
103	
104	    if (error instanceof MlflowHttpError) {
105	      throw error;
106	    }
107	
108	    if (error instanceof Error) {
109	      if (error.name === 'AbortError') {
110	        throw new Error(`Request timeout after ${timeout}ms`);
111	      }
112	      throw new Error(`API request failed: ${error.message}`);
113	    }
114	    throw new Error(`API request failed: ${String(error)}`);
115	  }
116	}
