118	function getDefaultTimeout(): number {
119	  const envTimeout = process.env.MLFLOW_HTTP_REQUEST_TIMEOUT;
120	  if (envTimeout) {
121	    const timeout = parseInt(envTimeout, 10);
122	    if (!isNaN(timeout) && timeout > 0) {
123	      return timeout;
124	    }
125	  }
126	  return 30000; // Default 30 seconds
127	}
