/**
 * Parse a trace ID into its location and OTel trace ID components.
 *
 * V4 trace IDs have the format `trace:/<location>/<otelTraceId>`. For such IDs,
 * this returns `[location, otelTraceId]`. For non-V4 IDs (e.g. `tr-<id>`), this
 * returns `[null, rawTraceId]`.
 *
 * @param traceId The trace ID to parse
 * @throws Error with message matching /Invalid trace ID format/ if the trace ID
 *   begins with the V4 prefix but is structurally malformed.
 */
export function parseTraceIdV4(traceId: string): [string | null, string] {
  if (traceId.startsWith(TRACE_ID_V4_PREFIX)) {
    const rest = traceId.slice(TRACE_ID_V4_PREFIX.length);
    const parts = rest.split('/');
    if (parts.length === 2 && parts[0] && parts[1]) {
      return [parts[0], parts[1]];
    }
    throw new Error(
      `Invalid trace ID format: ${traceId}. ` +
        `Expected format: ${TRACE_ID_V4_PREFIX}<location>/<trace_id>`,
    );
  }
  return [null, traceId];
}

/**
 * Construct a V4 trace ID from a location and an OTel trace ID.
 * @param location The trace location string (e.g. `catalog.schema.prefix`)
 * @param otelTraceId The hex-encoded OpenTelemetry trace ID
 */
export function constructTraceIdV4(location: string, otelTraceId: string): string {
  return `${TRACE_ID_V4_PREFIX}${location}/${otelTraceId}`;
}

/**
 * Generate a V3 trace ID (format `tr-<otelTraceId>`) from an OTel trace ID.
 * @param otelTraceId The hex-encoded OpenTelemetry trace ID
 */
export function generateTraceIdV3(otelTraceId: string): string {
  return `${TRACE_ID_PREFIX}${otelTraceId}`;
}
