/**
 * Experiment tag key holding the UC destination path (format `catalog.schema.prefix`).
 */
export const DATABRICKS_TRACE_DESTINATION_PATH_TAG =
  'mlflow.experiment.databricksTraceDestinationPath';

/**
 * Experiment tag key holding the OTLP spans storage table name.
 */
export const DATABRICKS_TRACE_SPAN_STORAGE_TABLE_TAG =
  'mlflow.experiment.databricksTraceSpanStorageTable';

/**
 * Experiment tag key holding the OTLP logs storage table name.
 */
export const DATABRICKS_TRACE_LOG_STORAGE_TABLE_TAG =
  'mlflow.experiment.databricksTraceLogStorageTable';

/**
 * Experiment tag key holding the annotations table name.
 */
export const DATABRICKS_TRACE_ANNOTATIONS_TABLE_TAG =
  'mlflow.experiment.databricksTraceAnnotationsTable';

/**
 * Resolve a Unity Catalog location from a set of experiment tags.
 *
 * Reads {@link DATABRICKS_TRACE_DESTINATION_PATH_TAG} and splits it by `.` into
 * catalog, schema, and table prefix. Returns null if the tag is absent, the path
 * does not split into exactly three segments, or any segment is empty.
 *
 * @param tags The experiment tags
 */
export function ucLocationFromExperimentTags(tags: Record<string, string>): {
  catalogName: string;
  schemaName: string;
  tablePrefix: string;
  otelSpansTableName: string;
  otelLogsTableName: string;
  annotationsTableName: string;
} | null {
  const path = tags[DATABRICKS_TRACE_DESTINATION_PATH_TAG];
  if (!path) {
    return null;
  }

  const segments = path.split('.');
  if (segments.length !== 3 || segments.some((segment) => segment === '')) {
    return null;
  }

  const [catalogName, schemaName, tablePrefix] = segments;
  return {
    catalogName,
    schemaName,
    tablePrefix,
    otelSpansTableName: tags[DATABRICKS_TRACE_SPAN_STORAGE_TABLE_TAG],
    otelLogsTableName: tags[DATABRICKS_TRACE_LOG_STORAGE_TABLE_TAG],
    annotationsTableName: tags[DATABRICKS_TRACE_ANNOTATIONS_TABLE_TAG],
  };
}
